INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (125, '8JT4', 'lemma', 'Concentration of the kernel', 'For real $\sigma > 2$ and integers $k \ge 0$ let $K_k(u) = u^k e^{-\sigma u}/k!$ for $u \ge 0$.
\begin{enumerate}
\item[(i)] For every real $a < \sigma$, $\displaystyle\int_0^\infty e^{au} K_k(u)\,du = (\sigma - a)^{-k-1}$.
\item[(ii)] There is $\sigma_0 > 3$ such that for every real $\sigma \ge \sigma_0$ there is $U_0 > 0$ with the following property: for every $U \ge U_0$, with $W = [U, \frac32 U]$ and $k = \lceil \frac54 \sigma U \rceil$,
\[ \int_{u \notin W} e^{2u} K_k(u)\,du \le 2\sigma^{-k}. \]
\end{enumerate}', NULL, 104, 13, 'published', 0, 1, '2026-11-24 20:20:00', '2026-11-24 20:20:00', 'claude', 'claude');
INSERT INTO revisions (entity, entity_key, revision, operation_id, snapshot_json, author) VALUES ('result', '125', 1, 'one-chain-8JT2-2026-11-24', '{"tag":"8JT4","type":"lemma","title":"Concentration of the kernel","statement_tex":"For real $\\sigma > 2$ and integers $k \\ge 0$ let $K_k(u) = u^k e^{-\\sigma u}/k!$ for $u \\ge 0$.\n\\begin{enumerate}\n\\item[(i)] For every real $a < \\sigma$, $\\displaystyle\\int_0^\\infty e^{au} K_k(u)\\,du = (\\sigma - a)^{-k-1}$.\n\\item[(ii)] There is $\\sigma_0 > 3$ such that for every real $\\sigma \\ge \\sigma_0$ there is $U_0 > 0$ with the following property: for every $U \\ge U_0$, with $W = [U, \\frac32 U]$ and $k = \\lceil \\frac54 \\sigma U \\rceil$,\n\\[ \\int_{u \\notin W} e^{2u} K_k(u)\\,du \\le 2\\sigma^{-k}. \\]\n\\end{enumerate}","section_id":104,"position":13,"listed":0,"aliases":["kernel-concentration"]}', 'claude');
